CL_NEW = 'of line, and Ask shows each answer from its first line.\n\n**Design step 2a: Observed Scene and Rank Fragility.** Observed Scene pairs the radar image\nwith a slick fingerprint: the shape drawn to its measured axes and bearing, north up, a\ncounting area, compact facts and an elongation bar. Rank Fragility shows every tested change\nas one dot, smallest first - blue where the leader held, amber where it flipped, the smallest\nflip ringed, each described on hover - beside the share that held. Notes fold into "How this\nis measured" in both.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 36 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 37: {len(writes)} files written, {skipped} already in place.")
